public static class MutationRulesQ {
 public static string? Field(string attribute,object definition)=>attribute switch{"cpu"=>"Cpu","power"=>"Power","capacitorNeed"=>"Capacitor","duration"=>"Cycle","maxRange"=>definition.GetType().GetProperty("Optimal")!=null?"Optimal":"Range","falloff"=>"Falloff","trackingSpeed"=>"Tracking","shieldBonus" or "armorDamageAmount" or "structureDamageAmount" or "shieldCapacity" or "armorHP"=>definition.GetType().GetProperty("Amount")!=null?"Amount":null,"energyNeutralizerAmount" or "powerTransferAmount"=>"Amount","speedFactor"=>definition is MobilityDefinition?"Speed":definition is EwarDefinition?"Strength":null,"signatureRadiusBonus"=>definition is MobilityDefinition?"Signature":null,"shieldRechargeRate"=>null,_=>null};
 public static T? Apply<T>(T? raw,MutationInstanceQ? m) where T:class {if(raw==null||m==null)return raw;if(ReferenceEquals(m.Original,raw)&&m.Cached is T cached)return cached;var clone=(T)typeof(object).GetMethod("MemberwiseClone",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(raw,null)!;foreach(var f in m.Fields){var property=raw.GetType().GetProperty(f.Key);if(property?.GetValue(raw) is not {} value||property.SetMethod==null)continue;double result=Convert.ToDouble(value)*f.Value;property.SetValue(clone,Convert.ChangeType(result,property.PropertyType));}m.Original=raw;m.Cached=clone;return clone;}
}
