public sealed partial class DemoWorld {
 public IEnumerable<(string Kind,int Slot,object State)> MutableModulesQ(){for(int i=0;i<Player.Weapons.Length;i++)yield return("weapon",i,Player.Weapons[i]);for(int i=0;i<Player.Ewar.Length;i++)yield return("ewar",i,Player.Ewar[i]);for(int i=0;i<Player.Defense.Length;i++)yield return("defense",i,Player.Defense[i]);for(int i=0;i<Player.Support.Length;i++)yield return("support",i,Player.Support[i]);for(int i=0;i<Player.Utilities.Length;i++)yield return("utility",i,Player.Utilities[i]);for(int i=0;i<Player.Mobility.Length;i++)yield return("mobility",i,Player.Mobility[i]);for(int i=0;i<Player.Enhancements.Length;i++)yield return("enhancement",i,Player.Enhancements[i]);}
 public string MutateModuleQ(string kind,int slot,int mutator){var state=MutableModulesQ().FirstOrDefault(m=>m.Kind==kind&&m.Slot==slot).State;var profile=CatalogQ.Data.Mutators.FirstOrDefault(m=>m.Type==mutator);if(!Docked||state==null||profile==null||ItemCount(CatalogQ.Item(mutator),true)<1)return "Dock with the source mutator and select an installed module.";var type=state.GetType();var raw=type.GetProperty("Definition")?.GetValue(state);string module=(string?)type.GetProperty("ModuleId")?.GetValue(state)??"";int input=UnifiedCatalog40.FindSourceId(module)??0;var map=profile.Mappings.FirstOrDefault(m=>m.Inputs.Contains(input));if(raw==null||map==null||type.GetProperty("MutationQ")?.GetValue(state)!=null||type.GetProperty("Active")?.GetValue(state) is true||type.GetProperty("Burnt")?.GetValue(state) is true||Convert.ToDouble(type.GetProperty("Damage")?.GetValue(state)??0)>0||state is DefenseState{MutatedE:true})return "Source eligibility requires a pristine inactive unmutated module.";var fields=new Dictionary<string,string>();foreach(var attribute in profile.Attributes){string? field=MutationRulesQ.Field(attribute.Name,raw);var property=field==null?null:raw.GetType().GetProperty(field);if(property?.GetValue(raw)==null||property.SetMethod==null||property.PropertyType is not {} t||t!=typeof(float)&&t!=typeof(double)&&t!=typeof(decimal))return "This mutator's live mapping is incomplete: "+attribute.Name+"; no item consumed.";fields[attribute.Name]=field!;}
  var outcome=new MutationInstanceQ{Mutator=mutator,InputType=input,ResultType=map.Output,Module=module,Instance=(string?)type.GetProperty("InstanceId")?.GetValue(state)??Guid.NewGuid().ToString("N")};foreach(var a in profile.Attributes){double f=a.Min+RollProductionE()*(a.Max-a.Min);outcome.Factors[a.Name]=f;outcome.Fields[fields[a.Name]]=f;}ChangeStack(CatalogQ.Item(mutator),true,-1);type.GetProperty("MutationQ")!.SetValue(state,outcome);type.GetProperty("Online")!.SetValue(state,false);SystemsQ.Mutations.Add(outcome);RecomputeWeaponFit();LogQ("Source-range module mutation / "+outcome.Instance+" / output type "+outcome.ResultType);return "";}
 public bool HasMutatedStockQ(string item,bool hangar)=>ConditionBanksD().Any(b=>b.List.Cast<object>().Any(e=>PropertyD(e,"State") is {} state&&(string?)PropertyD(state,"ModuleId")==item&&PropertyD(state,"MutationQ")!=null&&(bool?)PropertyD(e,"Hangar")==hangar));
 public CapitalHoldQ ActiveCapitalHoldQ {get{if(!SystemsQ.CapitalHolds.TryGetValue(Player.InstanceId,out var hold))SystemsQ.CapitalHolds[Player.InstanceId]=hold=new();return hold;}}
 public decimal CapitalVolumeQ(Dictionary<string,decimal> items)=>items.Sum(i=>i.Value*(decimal)ItemVolume(i.Key));
 public string TransferCapitalQ(string item,int amount,string hold,bool into){if(Commander.Capsule||amount<=0||hold is not("Fleet" or "Fuel"))return "A piloted hull, hold and positive quantity required.";double capacity=Player.Stat(hold=="Fleet"?"fleetHangarCapacity":"specialFuelBayCapacity");if(capacity<=0||hold=="Fuel"&&item is not("fuel" or "jump_fuel" or "sp_clonefuel"))return "Hull capacity or fuel identity not admitted.";var storage=hold=="Fleet"?ActiveCapitalHoldQ.Fleet:ActiveCapitalHoldQ.Fuel;bool hangar=Docked;if(into){if(ItemCount(item,hangar)<amount||CapitalVolumeQ(storage)+amount*(decimal)ItemVolume(item)>(decimal)capacity||ConditionBanksD().Any(b=>b.List.Cast<object>().Any(e=>PropertyD(e,"State") is {} state&&(string?)PropertyD(state,"ModuleId")==item&&(bool?)PropertyD(e,"Hangar")==hangar)))return "Owned repackaged input and hold capacity required.";ChangeStack(item,hangar,-amount);storage[item]=storage.GetValueOrDefault(item)+amount;}else{if(storage.GetValueOrDefault(item)<amount||!hangar&&CargoRoom(item)<amount*ItemVolume(item))return "Hold stock or cargo capacity insufficient.";storage[item]-=amount;ChangeStack(item,hangar,amount);}RecordRoleQ("Capital hold transfer");return "";}
 public string StoreMaintenanceQ(string berth){var ship=ParkedShips.FirstOrDefault(b=>b.Id==berth&&b.System==StationKey44);double capacity=Player.Stat("shipMaintenanceBayCapacity");if(!Docked||ship==null||capacity<=0||FleetCatalog.ById.GetValueOrDefault(ship.Ship.CombatHull)?.Value("volume") is not double volume||ActiveCapitalHoldQ.Ships.Sum(s=>FleetCatalog.ById.GetValueOrDefault(s.Ship.CombatHull)?.Value("volume")??100000)+volume>capacity)return "Dock with an owned fitted berth and compatible maintenance bay capacity.";ActiveCapitalHoldQ.Ships.Add(ship);ParkedShips.Remove(ship);RecordRoleQ("Maintenance bay storage");return "";}
 public string RecoverMaintenanceQ(string berth){var ship=ActiveCapitalHoldQ.Ships.FirstOrDefault(b=>b.Id==berth);if(!Docked||ship==null)return "Dock with a stored fitted ship.";ship.System=StationKey44;ParkedShips.Add(ship);ActiveCapitalHoldQ.Ships.Remove(ship);return "";}
 public string RecoverCargoShipQ(string id){var ship=SystemsQ.RecoveredShips.FirstOrDefault(s=>s.Id==id);if(!Docked||ship==null||ItemCount(ship.Ship.CombatHull,false)<1)return "Dock with the retained fitted hull in cargo.";ChangeStack(ship.Ship.CombatHull,false,-1);ship.System=StationKey44;ParkedShips.Add(ship);SystemsQ.RecoveredShips.Remove(ship);return "";}
 public void RecordRoleQ(string action){if(!SystemsQ.RoleEvents.TryGetValue(Player.InstanceId,out var events))SystemsQ.RoleEvents[Player.InstanceId]=events=[];events.Add(action);}
 public void ResolveCapitalLossQ(WreckD wreck){foreach(var berth in SystemsQ.RecoveredShips){string item=berth.Ship.CombatHull;if(wreck.Items.GetValueOrDefault(item)>wreck.Instances.Count(i=>i.Item==item))wreck.Instances.Add(new(){Id=berth.Id,Item=item,Bank="fleet-q",Json=JsonSerializer.Serialize(berth,WeaponCatalog.JsonOptions)});}SystemsQ.RecoveredShips.Clear();if(!SystemsQ.CapitalHolds.Remove(Player.InstanceId,out var hold))return;foreach(var i in hold.Fleet.Concat(hold.Fuel)){decimal dropped=decimal.Floor(i.Value*.5m);if(dropped>0)wreck.Items[i.Key]=wreck.Items.GetValueOrDefault(i.Key)+dropped;}foreach(var ship in hold.Ships)if(RollProductionE()<.5){string item=ship.Ship.CombatHull;wreck.Items[item]=wreck.Items.GetValueOrDefault(item)+1;wreck.Instances.Add(new(){Id=ship.Id,Item=item,Bank="fleet-q",Json=JsonSerializer.Serialize(ship,WeaponCatalog.JsonOptions)});}LogQ("Capital internal holds lost / sealed fitted ship drops / "+wreck.Id);}
